348→                value: "a".to_string(),
349→            },
350→            PromptOption {
351→                label: "Option B".to_string(),
352→                value: "b".to_string(),
353→            },
354→        ];
355→
356→        let prompt_type = PromptType::Select {
357→            options: options.clone(),
358→        };
359→
360→        if let PromptType::Select { options: stored } = prompt_type {
361→            assert_eq!(stored.len(), 2);
362→            assert_eq!(stored[0].value, "a");
363→        } else {
364→            panic!("Expected Select variant");
365→        }
366→    }
367→
368→    #[test]
369→    fn prompt_type_multiselect_stores_options() {
370→        let options = vec![PromptOption {
371→            label: "Feature 1".to_string(),
372→            value: "f1".to_string(),
