//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands
//! (`::error::`, `::warning::`, `::notice::`) so that annotations
//! appear inline on pull requests in CI environments.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }
}

impl Default for GithubActionsFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let level = match diag.severity {
                Severity::Error => "error",
                Severity::Warning => "warning",
                Severity::Hint => "notice",
            };

            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));
                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }
                if span.end_line != span.start_line {
                    params.push(format!("endLine={}", span.end_line));
                }
            }

            params.push(format!("title={}", diag.rule_id));

            let params_str = params.join(",");

            let mut message = diag.message.clone();
            if let Some(ref suggestion) = diag.suggestion {
                message.push_str(" | Suggestion: ");
                message.push_str(suggestion);
            }

            writeln!(writer, "::{level} {params_str}::{message}")?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Something is wrong",
        )
        .with_span(Span::new("config.yml", 10, 5, 10, 20))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::error file=config.yml,line=10,col=5,title=test-rule::Something is wrong\n"
        );
    }

    #[test]
    fn formats_warning_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("naming"),
            Severity::Warning,
            "Name has spaces",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::warning "));
        assert!(output.contains("title=naming"));
        assert!(output.contains("::Name has spaces\n"));
    }

    #[test]
    fn formats_hint_as_notice() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("style"),
            Severity::Hint,
            "Consider renaming",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_file_and_line() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("rule"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 42)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("file=config.yml"));
        assert!(output.contains("line=42"));
        // Column 1 should be omitted
        assert!(!output.contains("col="));
    }

    #[test]
    fn includes_column_when_not_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("rule"), Severity::Error, "msg")
                .with_span(Span::new("config.yml", 5, 8, 5, 20)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("col=8"));
    }

    #[test]
    fn includes_end_line_for_multiline_spans() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("rule"), Severity::Error, "msg")
                .with_span(Span::new("config.yml", 5, 1, 10, 20)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("endLine=10"));
    }

    #[test]
    fn omits_end_line_for_single_line_spans() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("rule"), Severity::Error, "msg")
                .with_span(Span::new("config.yml", 5, 1, 5, 20)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("endLine="));
    }

    #[test]
    fn no_location_params_without_span() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("rule"),
            Severity::Error,
            "msg",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("file="));
        assert!(!output.contains("line="));
        assert_eq!(output, "::error title=rule::msg\n");
    }

    #[test]
    fn appends_suggestion_to_message() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("rule"),
            Severity::Warning,
            "Bad name",
        )
        .with_suggestion("Use kebab-case")];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("::Bad name | Suggestion: Use kebab-case\n"));
    }

    #[test]
    fn formats_multiple_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "error one"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "warning one"),
            LintDiagnostic::new(RuleId::new("r3"), Severity::Hint, "hint one"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 3);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
        assert!(lines[2].starts_with("::notice "));
    }

    #[test]
    fn empty_diagnostics_produces_no_output() {
