//! Lint output formatters.
//!
//! This module provides formatters for outputting lint diagnostics
//! in different formats (human-readable, JSON, SARIF).

pub mod github_actions;
pub mod human;
pub mod json;
pub mod sarif;

use crate::lint::LintDiagnostic;
use std::io::Write;

